  left: auto !important;
  min-height: 6px !important;
  position: static !important;
}

html body header.universal-app-topbar .rebuilt-profile-xp-track.rebuilt-profile-xp-track {
  height: 4px !important;
  min-width: 42px !important;
  width: 42px !important;
}

html[data-theme="light"] body header.universal-app-topbar .rebuilt-profile-button.rebuilt-profile-button {
  background: #edf1f4 !important;
  border: 1px solid #d8e0e6 !important;
  box-shadow: none !important;
  color: #182632 !important;
}

html[data-theme="dark"] body header.universal-app-topbar .rebuilt-profile-button.rebuilt-profile-button {
  background: #0b1d2b !important;
  border: 1px solid #29465b !important;
  box-shadow: none !important;
  color: #f4f7f9 !important;
}

.marketplace-section-nav a,
.marketplace-section-nav button {
  border-radius: 0 !important;
  box-shadow: none !important;
  min-width: 142px;
}

.marketplace-section-nav a::before,
.marketplace-section-nav a::after,
.marketplace-section-nav button::before,
.marketplace-section-nav button::after {
  content: none !important;
}

.marketplace-section-nav .marketplace-section-filter {
  border-bottom-color: transparent !important;
  box-shadow: none !important;
}

.marketplace-section-nav .marketplace-section-filter:hover,
.marketplace-section-nav .marketplace-section-filter:focus-visible {
  background: rgba(255, 116, 23, .09) !important;
  border-bottom-color: #ff7417 !important;
  color: #e85f08 !important;
}

@media (min-width: 901px) {
  .marketplace-section-nav-inner {
    position: relative;
    transform: translateX(-48px);
  }
}

@media (max-width: 900px) {
  html body header.universal-app-topbar .rebuilt-profile-button.rebuilt-profile-button {
    min-width: 42px !important;
    padding: 0 5px !important;
    width: 42px !important;
  }

  html body header.universal-app-topbar .rebuilt-profile-button-copy.rebuilt-profile-button-copy,
  html body header.universal-app-topbar .rebuilt-profile-button > svg {
    display: none !important;
  }

  .marketplace-section-nav a,
  .marketplace-section-nav button {
    min-width: auto;
  }

  .marketplace-section-nav .marketplace-section-home,
  .marketplace-section-nav .marketplace-section-filter {
    display: none !important;
  }
}

/* Phone header: keep the brand/actions vertically centred and distribute the
   four marketplace links evenly instead of leaving a horizontal scroll gap. */
@media (max-width: 520px) {
  html body header.universal-app-topbar.universal-app-topbar {
    align-items: center !important;
  }

  html body header.universal-app-topbar .universal-home-navigation.universal-home-navigation,
  html body header.universal-app-topbar .universal-topbar-actions.universal-topbar-actions {
    align-self: center !important;
  }

  .marketplace-section-nav-inner {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    justify-content: center;
    width: 100%;
    overflow: hidden;
  }

  .marketplace-section-nav a,
  .marketplace-section-nav button {
    width: 100%;
    min-width: 0 !important;
    padding-inline: 3px !important;
    text-align: center;
  }

  html[data-theme="light"] body .marketplace-section-nav {
    border-bottom-color: #ff7417;
    box-shadow: none;
  }
}

/* Reuse the same vector MASKINES lettering in authentication views. */
html body .simple-auth-page .auth-maskines-brand .auth-maskines-wordmark {
  color: #172431;
  display: block;
  height: auto;
  width: clamp(190px, 34vw, 260px);
}
html body .simple-auth-page .auth-maskines-brand .auth-maskines-wordmark .maskines-wordmark-accent {
  fill: #ff7417;
}
html body main.auth-page.simple-auth-page .auth-centered .auth-maskines-brand .auth-maskines-wordmark {
  color: #172431;
}
html body .simple-auth-page .auth-maskines-brand > .auth-maskines-mark-light { display: block; }
html body .simple-auth-page .auth-maskines-brand > .auth-maskines-mark-dark { display: none; }
html[data-theme="dark"] body .simple-auth-page .auth-maskines-brand > .auth-maskines-mark-light { display: none; }
html[data-theme="dark"] body .simple-auth-page .auth-maskines-brand > .auth-maskines-mark-dark { display: block; }
html[data-theme="dark"] body main.auth-page.simple-auth-page .auth-centered .auth-maskines-brand .auth-maskines-wordmark {
  color: #f8fbff;
}

/* Keep login feedback next to the credentials that caused it. */
html body .simple-auth-page .auth-login-notice {
  align-items: flex-start;
  background: linear-gradient(135deg, rgba(111, 19, 29, 0.36), rgba(48, 13, 22, 0.64));
  border: 1px solid rgba(255, 98, 112, 0.48);
  border-radius: 10px;
  box-shadow: 0 10px 28px rgba(15, 3, 8, 0.18), inset 3px 0 0 #ff5969;
  color: #ffe8eb;
  display: flex;
  gap: 11px;
  margin: -4px 0 0;
  padding: 12px 14px;
  width: 100%;
}
html body .simple-auth-page .auth-login-notice-icon {
  align-items: center;
  background: rgba(255, 89, 105, 0.16);
  border: 1px solid rgba(255, 117, 130, 0.28);
  border-radius: 8px;
  color: #ff7b87;
  display: inline-flex;
  flex: 0 0 32px;
  height: 32px;
  justify-content: center;
  margin-top: 1px;
}
html body .simple-auth-page .auth-login-notice-copy {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
html body .simple-auth-page .auth-login-notice-copy strong {
  color: #fff4f5;
  font-size: 12px;
  font-weight: 850;
  line-height: 1.35;
}
html body .simple-auth-page .auth-login-notice-copy > span {
  color: #efb8bf;
  font-size: 11px;
  line-height: 1.45;
}
html body .simple-auth-page .auth-login-notice[data-tone="progress"] {
  background: linear-gradient(135deg, rgba(130, 68, 12, 0.26), rgba(49, 30, 12, 0.58));
  border-color: rgba(255, 139, 42, 0.42);
  box-shadow: 0 10px 28px rgba(18, 9, 2, 0.16), inset 3px 0 0 #ff841f;
}
html body .simple-auth-page .auth-login-notice[data-tone="progress"] .auth-login-notice-icon {
  background: rgba(255, 132, 31, 0.14);
  border-color: rgba(255, 153, 69, 0.25);
  color: #ff9b4a;
}
html body .simple-auth-page .auth-login-notice[data-tone="progress"] .auth-login-notice-copy strong,
html body .simple-auth-page .auth-login-notice[data-tone="progress"] .auth-login-notice-copy > span {
  color: #ffe2c4;
}
html body .simple-auth-page .auth-login-notice[data-tone="success"] {
  background: linear-gradient(135deg, rgba(13, 92, 59, 0.3), rgba(8, 49, 35, 0.6));
  border-color: rgba(58, 205, 137, 0.4);
  box-shadow: 0 10px 28px rgba(2, 18, 12, 0.16), inset 3px 0 0 #37c989;
}
html body .simple-auth-page .auth-login-notice[data-tone="success"] .auth-login-notice-icon {
  background: rgba(55, 201, 137, 0.14);
  border-color: rgba(86, 221, 162, 0.25);
  color: #61dda7;
}
html body .simple-auth-page .auth-login-notice[data-tone="success"] .auth-login-notice-copy strong,
html body .simple-auth-page .auth-login-notice[data-tone="success"] .auth-login-notice-copy > span {
  color: #d8f8e9;
}
@media (max-width: 480px) {
  html body .simple-auth-page .auth-login-notice {
    padding: 11px 12px;
  }
}
